FUNCTION_BLOCK FB_P16
VAR_INPUT
    processLength : USINT;
    sensor1 : BOOL;
    sensor2 : BOOL;
    sensor3 : BOOL;
    sensor4 : BOOL;
    sensor5 : BOOL;
    station1Start : BOOL;
    station2Complete : BOOL;
    station3Complete : BOOL;
    station4Complete : BOOL;
    processSequence : ARRAY[1..8] OF USINT;
END_VAR
VAR_OUTPUT
    conveyorLeft : BOOL := FALSE;
    conveyorRight : BOOL := FALSE;
END_VAR
VAR
    (* State: 0 = idle, 1 = transporting, 2 = processing, 3 = error. *)
    state : USINT := 0;
    stepIndex : INT := 0;
    currentStation : USINT := 1;
    targetStation : USINT := 0;
    activeLength : INT := 0;
    activeSequence : ARRAY[1..8] OF USINT;

    errorLatched : BOOL := FALSE;
    invalidSequence : BOOL;
    inputLength : INT;
    i : INT;

    previousStart : BOOL := FALSE;
    startEdge : BOOL;
    pendingStart : BOOL := FALSE;

    startupScans : USINT := 0;
    startupBlocked : BOOL;
    rightInhibitScans : USINT := 0;

    targetPresent : BOOL;
    currentPresent : BOOL;
    currentComplete : BOOL;
END_VAR

(* Each invocation is one 20 ms scan.
   C10 is interpreted literally: both first scans have stopped outputs.
   C9 is rolling: every left-output scan inhibits right for the next
   ten scans, not merely for ten scans following a rising edge.
   No reset input is provided; an error remains latched for this instance.
   Compilation and per-scan functional verification are not claimed. *)

conveyorLeft := FALSE;
conveyorRight := FALSE;

startEdge := station1Start AND NOT previousStart;
previousStart := station1Start;

startupBlocked := startupScans < 2;
IF startupBlocked THEN
    startupScans := startupScans + 1;
END_IF;

(* Validate before indexing. Also enforce the supplied sequence contract:
   intermediate entries are processing stations; the last entry is 5. *)
inputLength := USINT_TO_INT(processLength);
invalidSequence := (inputLength < 1) OR (inputLength > 8);

IF NOT invalidSequence THEN
    FOR i := 1 TO inputLength DO
        IF (processSequence[i] < 1) OR (processSequence[i] > 5) THEN
            invalidSequence := TRUE;
        END_IF;

        IF i < inputLength THEN
            IF (processSequence[i] < 2) OR (processSequence[i] > 4) THEN
                invalidSequence := TRUE;
            END_IF;
        ELSE
            IF processSequence[i] <> 5 THEN
                invalidSequence := TRUE;
            END_IF;
        END_IF;
    END_FOR;
END_IF;

IF invalidSequence THEN
    errorLatched := TRUE;
END_IF;

IF errorLatched THEN
    state := 3;
    pendingStart := FALSE;
ELSE
    (* Capture a qualified start during the startup output hold as well. *)
    IF (state = 0) AND startEdge AND sensor1 THEN
        pendingStart := TRUE;
    END_IF;

    IF NOT startupBlocked THEN
        CASE state OF
            0:
                IF pendingStart THEN
                    pendingStart := FALSE;
                    IF sensor1 THEN
                        (* Snapshot the recipe for this product. *)
                        activeLength := inputLength;
                        FOR i := 1 TO activeLength DO
                            activeSequence[i] := processSequence[i];
                        END_FOR;
                        stepIndex := 1;
                        currentStation := 1;
                        targetStation := activeSequence[stepIndex];
                        state := 1;
                    END_IF;
                END_IF;

            1:
                (* Transport and arrival are handled below. *)

            2:
                currentPresent := FALSE;
                currentComplete := FALSE;

                CASE currentStation OF
                    2:
                        currentPresent := sensor2;
                        currentComplete := station2Complete;
                    3:
                        currentPresent := sensor3;
                        currentComplete := station3Complete;
                    4:
                        currentPresent := sensor4;
                        currentComplete := station4Complete;
                END_CASE;

                (* Completion is a level-qualified signal; arrival alone
                   never authorizes departure from a processing station. *)
                IF currentPresent AND currentComplete THEN
                    IF (stepIndex >= 1) AND
                       (stepIndex < activeLength) THEN
                        stepIndex := stepIndex + 1;
                        targetStation := activeSequence[stepIndex];
                        state := 1;
                    ELSE
                        errorLatched := TRUE;
                        state := 3;
                    END_IF;
                END_IF;

            ELSE
                errorLatched := TRUE;
                state := 3;
        END_CASE;

        IF (state = 1) AND NOT errorLatched THEN
            targetPresent := FALSE;
            CASE targetStation OF
                2: targetPresent := sensor2;
                3: targetPresent := sensor3;
                4: targetPresent := sensor4;
                5: targetPresent := sensor5;
                ELSE
                    errorLatched := TRUE;
                    state := 3;
            END_CASE;

            IF NOT errorLatched THEN
                IF targetPresent THEN
                    (* Arrival has priority over motor energization. *)
                    currentStation := targetStation;
                    IF targetStation = 5 THEN
                        state := 0;
                        stepIndex := 0;
                        activeLength := 0;
                    ELSE
                        state := 2;
                    END_IF;
                ELSIF targetStation < currentStation THEN
                    conveyorLeft := TRUE;
                ELSIF targetStation > currentStation THEN
                    IF rightInhibitScans = 0 THEN
                        conveyorRight := TRUE;
                    END_IF;
                ELSE
                    (* A repeated station requires its sensor to be present;
                       no direction is meaningful until it is present. *)
                    conveyorLeft := FALSE;
                    conveyorRight := FALSE;
                END_IF;
            END_IF;
        END_IF;
    END_IF;
END_IF;

(* Final safety override. *)
IF errorLatched OR startupBlocked THEN
    conveyorLeft := FALSE;
    conveyorRight := FALSE;
END_IF;

(* Update after permission evaluation: the tenth scan following the
   last left scan is still inhibited; right is permitted on the eleventh. *)
IF conveyorLeft THEN
    rightInhibitScans := 10;
ELSIF rightInhibitScans > 0 THEN
    rightInhibitScans := rightInhibitScans - 1;
END_IF;

END_FUNCTION_BLOCK
